export function businessRoi(b, horizonHours) {
  const netPerHour = b.grossPerHour - b.costPerHour;
  const paybackHours = netPerHour > 0 ? b.price / netPerHour : 1 / 0;
  const profitAtHorizon = Math.round(netPerHour * horizonHours - b.price);
  return {
    business: b,
    netPerHour,
    paybackHours: Math.round(paybackHours * 10) / 10,
    profitAtHorizon,
    activeShare: Math.round(b.activeMinutes / 60 * 100),
    effectivePerHour: horizonHours > 0 ? Math.round(profitAtHorizon / horizonHours) : 0
  };
}
export const rankedBusinesses = (horizonHours) => BUSINESSES.map((b) => businessRoi(b, horizonHours)).sort((a, b) => a.paybackHours - b.paybackHours);
